from math import gcd
from typing import List, Tuple

def affine_table(q: int, a: int, b: int) -> List[Tuple[int, int]]:
    if q <= 0: raise ValueError("q must be positive")
    return [(x, (a*x+b) % q) for x in range(q)]

def is_bijection(q: int, a: int, b: int) -> bool:
    return len({y for _, y in affine_table(q,a,b)}) == q

if __name__ == "__main__":
    for a in (5,4):
        print(a, gcd(a,12)==1, is_bijection(12,a,3), affine_table(12,a,3))

from math import gcd
from typing import List

def units(q: int) -> List[int]:
    if q <= 0: raise ValueError("q must be positive")
    return [a for a in range(q) if gcd(a,q)==1]

if __name__ == "__main__":
    for q in (8,12,15,30,40):
        us=units(q)
        print(f"q={q}, units={us}, phi={len(us)}, density={len(us)/q:.4f}")

from typing import Sequence, Tuple

def advantage_witness(delta: float, values: Sequence[float]) -> Tuple[int,float]:
    if not values or delta > sum(values): raise ValueError("invalid hybrid data")
    i=max(range(len(values)), key=values.__getitem__)
    assert values[i] >= delta/len(values)
    return i, values[i]

if __name__ == "__main__":
    gaps=[.01,.02,.04,.03,.08,.02,.03,.01]
    i,g=advantage_witness(.24,gaps)
    print(f"witness={i}, gap={g}, guaranteed threshold={.24/len(gaps)}")

