from math import gcd
from typing import Tuple

def extended_gcd(a: int, b: int) -> Tuple[int,int,int]:
    if b == 0: return abs(a), 1 if a >= 0 else -1, 0
    g,x1,y1=extended_gcd(b,a%b)
    return g,y1,x1-(a//b)*y1

def affine_inverse(q: int, a: int, b: int, y: int) -> int:
    if q <= 0: raise ValueError("q must be positive")
    g,x,_=extended_gcd(a,q)
    if g != 1: raise ValueError("a is not a unit modulo q")
    return (x*(y-b)) % q

from math import gcd
from random import Random
from typing import List, Tuple

def sample_units(q: int, count: int, seed: int=0) -> Tuple[List[int],int]:
    if q <= 0 or count < 0: raise ValueError("invalid input")
    rng=Random(seed); out: List[int]=[]; trials=0
    while len(out)<count:
        trials += 1; a=rng.randrange(q)
        if gcd(a,q)==1: out.append(a)
    return out,trials

from typing import Sequence, Tuple

def largest_hybrid_contribution(delta: float, gaps: Sequence[float]) -> Tuple[int,float,float]:
    if not gaps: raise ValueError("nonempty hybrid required")
    if sum(gaps) < delta: raise ValueError("total gap is too small")
    index=max(range(len(gaps)),key=gaps.__getitem__)
    threshold=delta/len(gaps)
    assert gaps[index] >= threshold
    return index,gaps[index],threshold

